import { useState } from "react";

const styles = {
  nav: {
    display: "flex",
    justifyContent: "space-between",
    alignItems: "center",
    padding: "12px 24px",
    background: "#1e40af",
    color: "white",
  },
  logo: {
    fontSize: "20px",
    fontWeight: "bold",
  },
  links: {
    display: "flex",
    gap: "20px",
  },
  link: {
    color: "white",
    textDecoration: "none",
    fontWeight: "500",
  },
  account: {
    position: "relative",
  },
  accountBtn: {
    background: "white",
    color: "#1e40af",
    border: "none",
    padding: "6px 12px",
    borderRadius: "6px",
    cursor: "pointer",
  },
  dropdown: {
    position: "absolute",
    top: "40px",
    right: "0",
    background: "white",
    color: "black",
    borderRadius: "6px",
    boxShadow: "0 2px 8px rgba(0,0,0,0.2)",
    overflow: "hidden",
  },
  dropdownItem: {
    display: "block",
    padding: "10px 15px",
    textDecoration: "none",
    color: "black",
  },
};

const Navbar = () => {
  const [open, setOpen] = useState(false);

  return (
    <nav style={styles.nav}>
      {/* Logo */}
      <div style={styles.logo}>
        🚌 IBTS
      </div>

      {/* Links */}
      <div style={styles.links}>
        <a href="/" style={styles.link}>Home</a>
        <a href="/routes" style={styles.link}>Routes</a>
        <a href="/bookings" style={styles.link}>My Bookings</a>
      </div>

      {/* Account Section */}
      <div style={styles.account}>
        <button onClick={() => setOpen(!open)} style={styles.accountBtn}>
          👤 My Account
        </button>

        {open && (
          <div style={styles.dropdown}>
            <a href="/login" style={styles.dropdownItem}>Login</a>
            <a href="/register" style={styles.dropdownItem}>Register</a>
            <a href="/profile" style={styles.dropdownItem}>Profile</a>
          </div>
        )}
      </div>
    </nav>
  );
};

export default Navbar;
